@router.post("/api/gitlab/scan")
def trigger_gitlab_scan(body: GitLabScanModel):
    """Triggers automated discovery, cloning, and full-spectrum auditing of all GitLab projects."""
    try:
        from auditors.gitlab_integration import GitLabIntegrator
        if body.gitlab_url or body.instance:
            res = GitLabIntegrator(gitlab_url=body.gitlab_url, token=body.token, instance=body.instance).scan_all_projects()
        else:
            from auditors.gitlab_integration import scan_all_instances
            res = scan_all_instances()  # no explicit target -> every configured instance
        return {"status": "success", "summary": res}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



